#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007

int cmp(const void *a, const void *b) {
    return *(int*)b - *(int*)a;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int A[N], B[M];
    for (int i = 0; i < N; i++) scanf("%d", &A[i]);
    for (int j = 0; j < M; j++) scanf("%d", &B[j]);

    qsort(A, N, sizeof(int), cmp);
    qsort(B, M, sizeof(int), cmp);

    long long ans = 1;
    int r = 0, c = 0;
    int filled = 0;

    for (int v = N * M; v >= 1; v--) {
        while (r < N && A[r] == v) r++;
        while (c < M && B[c] == v) c++;

        int row_has = (r > 0 && A[r-1] >= v);
        int col_has = (c > 0 && B[c-1] >= v);

        if (row_has && col_has) {
            // v is both a row max and column max
            // exactly one cell is forced
            filled++;
            // multiply by 1, do nothing
        } else if (row_has) {
            // v is only a row max
            filled++;
        } else if (col_has) {
            // v is only a column max
            filled++;
        } else {
            long long avail = (long long)r * c - filled;
            if (avail <= 0) {
                ans = 0;
                break;
            }
            ans = (ans * avail) % MOD;
            filled++;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

