#define MOD 1000000007LL

static int cmp_desc(const void *a, const void *b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (y - x);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *A = (int*)malloc(sizeof(int) * N);
    int *B = (int*)malloc(sizeof(int) * M);

    for (int i = 0; i < N; i++) scanf("%d", &A[i]);
    for (int j = 0; j < M; j++) scanf("%d", &B[j]);

    qsort(A, N, sizeof(int), cmp_desc);
    qsort(B, M, sizeof(int), cmp_desc);

    /* Check duplicates in A or B: impossible */
    for (int i = 1; i < N; i++) {
        if (A[i] == A[i - 1]) {
            printf("0\n");
            free(A); free(B);
            return 0;
        }
    }
    for (int j = 1; j < M; j++) {
        if (B[j] == B[j - 1]) {
            printf("0\n");
            free(A); free(B);
            return 0;
        }
    }

    long long ans = 1;
    int ia = 0, ib = 0;

    for (int x = N * M; x >= 1; x--) {
        int inA = (ia < N && A[ia] == x);
        int inB = (ib < M && B[ib] == x);

        if (inA && inB) {
            /* Must be placed at the intersection of that row and column */
            ia++;
            ib++;
        } else if (inA) {
            /* Row maximum fixed, choose among already opened columns */
            ans = (ans * ib) % MOD;
            ia++;
        } else if (inB) {
            /* Column maximum fixed, choose among already opened rows */
            ans = (ans * ia) % MOD;
            ib++;
        } else {
            /* Can be placed in any free cell among opened rows/columns */
            long long available = 1LL * ia * ib - ((long long)(N * M - x));
            if (available <= 0) {
                printf("0\n");
                free(A); free(B);
                return 0;
            }
            ans = (ans * available) % MOD;
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(B);
    return 0;
}

