    }

    // Count occurrences in A and B
    vector<int> cntA(N * M + 1, 0), cntB(N * M + 1, 0);
    for (int x : A) cntA[x]++;
    for (int x : B) cntB[x]++;

    // Check that each value appears at most once in A and at most once in B
    for (int v = 1; v <= N * M; v++) {
        if (cntA[v] > 1 || cntB[v] > 1) {
            cout << 0 << '\n';
            return 0;
        }
    }

    int64 ans = 1;
    int r = 0, c = 0; // rows/cols with max >= current value
    int filled = 0;   // cells already taken in intersection

    for (int v = N * M; v >= 1; v--) {
        if (cntA[v] && cntB[v]) {
            // Must be placed at intersection of new row and new column
            ans = ans * 1 % MOD;
            r++;
            c++;
            filled++; // the intersection cell itself
        } else if (cntA[v]) {
            // Row max, choose column among unfixed columns
            ans = ans * c % MOD;
            r++;
        } else if (cntB[v]) {
            // Column max, choose row among unfixed rows
            ans = ans * r % MOD;
            c++;
        } else {
            // Free cell: r*c - filled positions already used
            int64 choices = (int64)r * c - filled;
            if (choices <= 0) {
                ans = 0;
                break;
            }
            ans = ans * choices % MOD;
            filled++;
        }
    }

    cout << ans % MOD << '\n';
