    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[M];

        int maxA = 0, maxB = 0;
        Map<Integer, Integer> rowMaxCount = new HashMap<>();
        Map<Integer, Integer> colMaxCount = new HashMap<>();

        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            maxA = Math.max(maxA, A[i]);
            rowMaxCount.put(A[i], rowMaxCount.getOrDefault(A[i], 0) + 1);
        }
        for (int j = 0; j < M; j++) {
            B[j] = sc.nextInt();
            maxB = Math.max(maxB, B[j]);
            colMaxCount.put(B[j], colMaxCount.getOrDefault(B[j], 0) + 1);
        }

        if (maxA != maxB) {
            System.out.println(0);
            return;
        }

        // Check that each value appears at most once as row max and column max
        for (int key : rowMaxCount.keySet()) {
            if (rowMaxCount.get(key) > 1) {
                System.out.println(0);
                return;
            }
        }
        for (int key : colMaxCount.keySet()) {
            if (colMaxCount.get(key) > 1) {
                System.out.println(0);
                return;
            }
        }

        int totalCells = N * M;
        long ans = 1;
        int rowsDone = 0;
        int colsDone = 0;

        // Process values from high to low
        for (int v = totalCells; v >= 1; v--) {
            boolean isRowMax = rowMaxCount.containsKey(v);
            boolean isColMax = colMaxCount.containsKey(v);

            if (isRowMax && isColMax) {
                // Must be placed at intersection
                rowsDone++;
                colsDone++;
            } else if (isRowMax) {
                // Place somewhere in row, column not yet having max
                ans = (ans * (M - colsDone)) % MOD;
                rowsDone++;
            } else if (isColMax) {
                ans = (ans * (N - rowsDone)) % MOD;
                colsDone++;
            } else {
                // Neither row nor column max
                long available = (long)(N - rowsDone) * (M - colsDone);
                // Subtract numbers that will be placed later as row/col maxes
                long remainingSpecial = (N - rowsDone) + (M - colsDone);
                available -= remainingSpecial;
                if (available <= 0) {
                    System.out.println(0);
                    return;
                }
                ans = (ans * available) % MOD;
            }
        }

        System.out.println(ans);
    }
}

