import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        int[] A = new int[N];
        int[] B = new int[M];

        for (int i = 0; i < N; i++) A[i] = fs.nextInt();
        for (int j = 0; j < M; j++) B[j] = fs.nextInt();

        // Check duplicates in A and B, and mark existence.
        boolean[] inA = new boolean[N * M + 1];
        boolean[] inB = new boolean[N * M + 1];

        for (int x : A) {
            if (inA[x]) {
                System.out.println(0);
                return;
            }
            inA[x] = true;
        }
        for (int x : B) {
            if (inB[x]) {
                System.out.println(0);
                return;
            }
            inB[x] = true;
        }

        Arrays.sort(A);
        Arrays.sort(B);

        long ans = 1L;

        int rowCnt = 0; // number of rows whose maximum >= current value
        int colCnt = 0; // number of columns whose maximum >= current value

        int ai = N - 1;
        int bi = M - 1;

        for (int x = N * M; x >= 1; x--) {
            if (ai >= 0 && A[ai] == x) {
                rowCnt++;
                ai--;
            }
            if (bi >= 0 && B[bi] == x) {
                colCnt++;
                bi--;
            }

            boolean a = inA[x];
            boolean b = inB[x];

            if (a && b) {
                // Must be placed at the unique intersection.
                continue;
            } else if (a) {
                // Must be in the row whose max is x, choose among available columns.
                ans = ans * colCnt % MOD;
            } else if (b) {
                // Must be in the column whose max is x, choose among available rows.
                ans = ans * rowCnt % MOD;
            } else {
                // Can be placed in any already "active" cell not used yet.
                long usedGreater = (long) (N * M - x);
                long available = (long) rowCnt * colCnt - usedGreater;
                if (available <= 0) {
                    System.out.println(0);
                    return;
                }
                ans = ans * available % MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
